create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_FACT_REAL_ESTATE_LIFECYCLE_1 (
	REAL_ESTATE_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the real estate object.',
	REAL_ESTATE_NR VARCHAR(20) NOT NULL COMMENT 'The number which uniquely identifies a real estate object within a country_1 organization.',
	REAL_ESTATE_NAME VARCHAR(100) NOT NULL COMMENT 'The name for the real estate object.',
	REAL_ESTATE_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the subtype discriminator for real estate objects.',
	REAL_ESTATE_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the lifecycle status_1 for real estate objects. (This is the business lifecycle, so it might differ from the status_1 code shown in the source system.)',
	PRECONTRACT_DT DATE COMMENT 'The date when the precontract / letter of intent for this real estate object was signed.',
	CONTRACT_DT DATE COMMENT 'The date when the contract for this real estate object was signed.',
	CONSTRUCTION_START_DT DATE COMMENT 'The date when construction started for this real estate object.',
	CONSTRUCTION_END_DT DATE COMMENT 'The date when construction finished for this real estate object.',
	PLANNED_OPEN_DT DATE COMMENT 'The date when this real estate object was intended to open.',
	OPEN_DT DATE COMMENT 'The date when this real estate object was opened.',
	OPENING_REASON_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the reason why a real estate object has been opened. (E.g. it was a new building, or it replaced an existing building.)',
	TEMP_CLOSING_START_DT DATE COMMENT 'The date of the beginning of the last temporary closing period for this real estate object.',
	TEMP_CLOSING_END_DT DATE COMMENT 'The date of the end of the last temporary closing period for this real estate object.',
	CLOSED_BUS_DAYS_CNT NUMBER(38,0) COMMENT 'The number of business days the real estate object remained closed.',
	TEMP_CLOSING_REASON_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the reason, why a real estate object has been temporarily closed.',
	PLANNED_CLOSE_DT DATE COMMENT 'The date when this real estate object was inteded to be closed.',
	CLOSE_DT DATE COMMENT 'The date when this real estate object was closed.',
	CLOSING_REASON_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the reason, why a real estate object has been (permanently) closed.',
	PROJECT_CANCEL_DT DATE COMMENT 'The date when the Schwarz Group had no intention to build a real estate object any more, i.e. when the project was cancelled.',
	PROJECT_CANCEL_REASON_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the reason, why a real estate project was (pre-maturely) terminated.',
	PROJECT_TERM_DT DATE COMMENT 'The date when the project was terminated, i.e. when the real estate object was closed and there were no legal obligations any more.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_FACT_REAL_ESTATE_LIFECYCLE primary key (REAL_ESTATE_SID)
)COMMENT='This (accumulating snapshot_1) fact tracks the lifecycle of a real estate object'
;